/* You can add global styles to this file, and also import other style files */
@import 'material-icons/iconfont/material-icons.css';

html, body {
  height: 100%;
}

body {
  margin: 0;
  font-family: Roboto, "Helvetica Neue", sans-serif;
}

/* Top bar */
.topBar {
  background-color: #005d87 !important;
  color: white !important;
  border-bottom: 3px solid coral !important;
  padding-top: 1.7em !important;
  padding-bottom: 1.7em !important;
}

/* Bottom bar */
.toolbarNav {
  background-color: #005d87 !important;
}

button {
  cursor: default !important;
}

/* Button styling */
button.text-button {
  background-color: #005d87 !important;
  color: white !important;
  color: black;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 70px;
  width: auto;
  height: auto;
  padding: 10px;
  border-radius: 8px !important;
}

button.text-blue-button {
  background-color: white;
  border: 2px solid #005d87;
  color: black;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 70px;
  width: auto;
  height: auto;
  padding: 10px;
  border-radius: 8px !important;
}

button.blue-icon-button {
  background-color: white;
  color: #005d87;
  display: flex;
  align-items: center;
  justify-content: center;
}

button.bottom-toolbar-button {
  background-color: white;
  color: #005d87;
  display: flex;
  align-items: center;
  justify-content: center;
}


/* Text fields */
mat-form-field.mat-mdc-form-field {
  font-size: 18px;
  font-weight: bold;
  color: #004165;
}

.mdc-floating-label {
  font-weight: 600 !important;
}

.mat-mdc-form-field-error {
  font-weight: 600 !important;
}

.mat-mdc-select {
  font-weight: 600 !important;
}

.mat-mdc-list-base.mat-mdc-list-base .mdc-list-item--selected .mdc-list-item__primary-text, .mat-mdc-list-base.mat-mdc-list-base .mdc-list-item--activated .mdc-list-item__primary-text {
  color: black;
}


.mat-mdc-radio-button.mat-accent {
  --mdc-radio-selected-icon-color: coral !important;
  --mdc-radio-selected-focus-icon-color: coral !important;
  --mdc-radio-selected-hover-icon-color: coral !important;
  --mdc-radio-selected-pressed-icon-color: coral !important;
  --mat-radio-ripple-color: coral !important;
  --mat-radio-checked-ripple-color: coral !important;
}
